begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok((select bool_and(not has_table_privilege('authenticated',t,'SELECT,INSERT,UPDATE,DELETE') and not has_table_privilege('anon',t,'SELECT,INSERT,UPDATE,DELETE')) from unnest(array['private.lifecycle_requests','private.trip_recognition']) t),'Recognition and retry state are private');
select ok((select bool_and(prosecdef and pg_get_userbyid(proowner)='carrier_security' and proconfig @> array['search_path=""']) from pg_proc where oid in ('public.dispatch_trip(uuid,uuid,integer,jsonb)'::regprocedure,'public.arrive_trip(uuid,uuid,integer,jsonb)'::regprocedure,'public.correct_trip_operation(text,uuid,uuid,integer,jsonb)'::regprocedure,'public.get_trip_history(uuid,integer)'::regprocedure)),'Lifecycle endpoints have restricted owner and empty search path');
select ok((select prosecdef and pg_get_userbyid(proowner)='carrier_earnings' and proconfig @> array['search_path=""'] from pg_proc where oid='private.post_dispatch_earnings(uuid,date,text)'::regprocedure),'Earnings writer has separate restricted owner');
select ok((select not rolcanlogin and not rolinherit and not rolbypassrls and not rolsuper from pg_roles where rolname='carrier_earnings'),'Earnings owner cannot log in or bypass RLS');
select ok(not pg_has_role('authenticated','carrier_earnings','MEMBER') and not pg_has_role('anon','carrier_earnings','MEMBER') and not pg_has_role('postgres','carrier_earnings','SET'),'Clients have no earnings membership; migration administrator has no SET permission');
select ok(not has_schema_privilege('carrier_earnings','public','CREATE') and not has_schema_privilege('carrier_earnings','private','CREATE'),'Earnings owner cannot replace functions');
select ok(has_table_privilege('carrier_earnings','public.journal_lines','INSERT') and not has_table_privilege('carrier_earnings','public.journal_lines','UPDATE,DELETE') and not has_table_privilege('carrier_earnings','public.financial_events','UPDATE,DELETE'),'Earnings writes are append only');
select ok(not has_table_privilege('carrier_security','public.journal_lines','INSERT,UPDATE,DELETE') and not has_table_privilege('carrier_security','public.financial_events','INSERT,UPDATE,DELETE'),'General command owner cannot directly write money');
select ok(not has_function_privilege('authenticated','private.post_dispatch_earnings(uuid,date,text)','EXECUTE') and not has_function_privilege('anon','private.post_dispatch_earnings(uuid,date,text)','EXECUTE') and has_function_privilege('carrier_security','private.post_dispatch_earnings(uuid,date,text)','EXECUTE'),'Only lifecycle owner may invoke private earnings interface');
select ok(not has_function_privilege('authenticated','private.run_trip_lifecycle(text,uuid,uuid,integer,jsonb)','EXECUTE'),'Client cannot invoke private lifecycle engine');
select ok(not has_function_privilege('anon','public.dispatch_trip(uuid,uuid,integer,jsonb)','EXECUTE') and has_function_privilege('authenticated','public.dispatch_trip(uuid,uuid,integer,jsonb)','EXECUTE'),'Dispatch requires signed in role');
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select throws_ok($$select public.dispatch_trip(gen_random_uuid(),gen_random_uuid(),1,'{}')$$,'42501','FORBIDDEN','Identity required for dispatch');
select throws_ok($$select public.arrive_trip(gen_random_uuid(),gen_random_uuid(),1,'{}')$$,'42501','FORBIDDEN','Identity required for arrival');
select throws_ok($$select public.correct_trip_operation('CORRECT_OPERATION',gen_random_uuid(),gen_random_uuid(),1,'{}')$$,'42501','FORBIDDEN','Identity required for corrections');
select throws_ok($$select public.get_trip_history(gen_random_uuid())$$,'42501','FORBIDDEN','Identity required for history');
reset role;
select * from finish();
rollback;
